#include "model_runner.h"
#include <TensorFlowLite.h>
#include <tensorflow/lite/micro/all_ops_resolver.h>
#include <tensorflow/lite/micro/micro_interpreter.h>
#include <tensorflow/lite/schema/schema_generated.h>

#include "model_data.h"           /* generated by model/convert.py --export-c-array */
#include "model_config.h"

#define TENSOR_ARENA_SIZE (96 * 1024)
static uint8_t tensor_arena[TENSOR_ARENA_SIZE];

static tflite::MicroInterpreter *interpreter;
static uint32_t last_inference_us;

void model_init(void)
{
    const tflite::Model *model = tflite::GetModel(g_model_data);
    static tflite::AllOpsResolver resolver;
    static tflite::MicroInterpreter static_interpreter(
        model, resolver, tensor_arena, TENSOR_ARENA_SIZE);
    interpreter = &static_interpreter;
    interpreter->AllocateTensors();
}

void model_run(const int8_t *input, int8_t *output)
{
    int8_t *in = interpreter->input(0)->data.int8;
    for (int i = 0; i < MODEL_INPUT_SIZE; i++) in[i] = input[i];

    uint32_t t0 = micros();
    interpreter->Invoke();
    last_inference_us = micros() - t0;

    int8_t *out = interpreter->output(0)->data.int8;
    for (int i = 0; i < MODEL_NUM_CLASSES; i++) output[i] = out[i];
}

uint32_t model_inference_time_us(void)
{
    return last_inference_us;
}
